import json

def _same(a, b):
    return type(a) is type(b) and a == b

def _render(v):
    return json.dumps(v, sort_keys=True)

def _walk(path, a, b, out):
    if type(a) is dict and type(b) is dict:
        for k in set(a) | set(b) — need to handle keys. Actually, keys might not be sortable? JSON keys are strings; but dict keys could be arbitrary hashables. Sort them? Not needed since the final output is sorted anyway. Iterate union of keys:
        for k in a.keys() | b.keys():
            kp = path + "." + str(k)
            if k in a and k in b: _walk(kp, a[k], b[k], out)
            elif k in a: out.append(f"- {kp}: {_render(a[k])}")
            else: out.append(f"+ {kp}: {_render(b[k])}")
    elif type(a) is list and type(b) is list:
        n = min(len(a), len(b))
        for i in range(n): _walk(path+f"[{i}]", a[i], b[i], out)
        for i in range(n, len(a)): out.append(f"- {path}[{i}]: {_render(a[i])}")
        for i in range(n, len(b)): out.append(f"+ {path}[{i}]: {_render(b[i])}")
    elif _same(a, b):
        pass
    else:
        out.append(f"~ {path}: {_render(a)} -> {_render(b)}")

def diff(a, b):
    out = []
    _walk("$", a, b, out)
    return sorted(out)

